const queries = ["nonprofit or impact startup announces new funding round or closes Series A","organization expands into new market or opens new office","nonprofit launches new program or new initiative","organization appoints new CEO, CFO, or Chief Development Officer","strategic partnership between company and nonprofit or foundation","nonprofit awarded multi-year or seven-figure grant"];
const since = new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString();
return queries.map(q => ({json: {query: q, body: Object.assign(
  {query: q, type: "auto", numResults: 25, startPublishedDate: since, contents: {text: {maxCharacters: 1500}, summary: true}},
  (typeof domains !== "undefined") ? {includeDomains: domains} : {}
)}}));

const domains = ["layoffwatcher.com","layoffhedge.com","businesswire.com","prnewswire.com","prlog.org","circleacts.org"];
const queries = ["company announces layoffs, staff reductions, or workforce reduction","organization facing budget shortfall or funding gap","nonprofit program suspended or closed due to lack of funding","organization announces restructuring plan or restructuring charges","organization discloses going concern risk or material uncertainty","nonprofit or charity running a deficit budget","nonprofit launches emergency or urgent fundraising appeal"];
const since = new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString();
return queries.map(q => ({json: {query: q, body: Object.assign(
  {query: q, type: "auto", numResults: 25, startPublishedDate: since, contents: {text: {maxCharacters: 1500}, summary: true}},
  (typeof domains !== "undefined") ? {includeDomains: domains} : {}
)}}));

// no domain restriction
const queries = ["emergency grant for nonprofit, church, or ministry","capital campaign over budget with cost overruns","bridge financing for mission-driven or impact organization","unexpected windfall grant or donation to community organization","community organization facing financial challenges"];
const since = new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString();
return queries.map(q => ({json: {query: q, body: Object.assign(
  {query: q, type: "auto", numResults: 25, startPublishedDate: since, contents: {text: {maxCharacters: 1500}, summary: true}},
  (typeof domains !== "undefined") ? {includeDomains: domains} : {}
)}}));

const out = [];
for (const item of $input.all()) {
  if (item.json.error) continue;
  const results = item.json.results || [];
  for (const r of results) out.push({json: {...r, signal_type: "growth", signal_source: "core"}});
}
return out;

